import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十四卦 復 地雷復 坤上震下","description":"周易 - 第二十四卦 復 地雷復 坤上震下","frontmatter":{"title":"第二十四卦 復 地雷復 坤上震下","description":"周易 - 第二十四卦 復 地雷復 坤上震下"},"headers":[],"relativePath":"classics/zhouyi/025.md","filePath":"classics/zhouyi/025.md"}'),l={name:"classics/zhouyi/025.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="復" tabindex="-1">復 <a class="header-anchor" href="#復" aria-label="Permalink to “復”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。出入無疾，朋來無咎。反覆其道，七日來複，利有攸往。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>復亨；剛反，動而以順行，是以出入無疾，朋來無咎。反覆其道，七日來複，天行也。利有攸往，剛長也。復其見天地之心乎？</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雷在地中，復；先王以至日閉關，商旅不行，後不省方。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>不復遠，無只 悔，元吉。象曰：不遠之復，以修身也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>休復，吉。象曰：休復之吉，以下仁也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>頻復，厲無咎。象曰：頻復之厲，義無咎也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>中行獨復。象曰：中行獨復，以從道也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>敦復，無悔。象曰：敦復無悔，中以自考也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>迷復，兇，有災眚。用行師，終有大敗，以其國君，兇；至於十年，不克徵。象曰：迷復之兇，反君道也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
